insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000001', 'calder-lounge-sofa', 'Calder Lounge Sofa', 'A deep three-seat sofa on a kiln-dried white oak frame. The boxed linen cushions stay square, and the arms are slim enough to sit beside a side table.', to_jsonb(array['Width 86 in · Depth 38 in · Height 31 in · Seat height 17 in', 'Kiln-dried oak frame with mortise-and-tenon joints', 'Down-and-feather wrap over high-density foam', 'Removable covers, dry clean']::text[]), 248000, true, true, 'sofas Natural oak Linen Sage Walnut Linen Ember Natural oak Boucle Ivory', '2026-02-11T00:00:00Z');
