insert into public.reviews (id, product_id, author_name, rating, title, body, created_at) values ('00000005-0000-4000-8000-000000000001', '00000002-0000-4000-8000-000000000001', 'Helen Cho', 5, 'The seat is actually deep', 'We sit sideways on it to read. The oak frame does not creak, and the sage linen looks better after a month than it did in the crate.', '2026-08-14T00:00:00Z');
insert into public.reviews (id, product_id, author_name, rating, title, body, created_at) values ('00000005-0000-4000-8000-000000000002', '00000002-0000-4000-8000-000000000001', 'Marcus Adeyemi', 4, 'Worth the wait', 'Six weeks from order to delivery. The cushions are firm in a good way. I wish the ember linen had been in stock.', '2026-09-02T00:00:00Z');
insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-000000000002', '00000001-0000-4000-8000-000000000001', 'ember-sectional', 'Ember Sectional', 'A two-piece sectional with a chaise long enough for a person and a dog. The terracotta upholstery is a heavy cotton weave that hides the Tuesday of it all.', to_jsonb(array['Overall 112 in · Chaise depth 64 in · Height 30 in', 'Hardwood frame, sinuous springs', 'Performance cotton, spot clean', 'Pieces join with steel brackets, no tools']::text[]), 428000, true, false, 'sofas Oak legs Cotton Ember Blackened steel Cotton Sand', '2026-04-02T00:00:00Z');
