insert into public.reviews (id, product_id, author_name, rating, title, body, created_at) values ('00000005-0000-4000-8000-000000000003', '00000002-0000-4000-8000-000000000002', 'Priya Shah', 5, 'Holds a crowd', 'Thanksgiving for eight, and the chaise was the prize seat. The ember color is quieter in person than the photograph.', '2026-07-19T00:00:00Z');
insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-000000000003', '00000001-0000-4000-8000-000000000001', 'marlowe-settee', 'Marlowe Settee', 'A tight-back settee for an entry or the foot of a bed. The seat is firmer than the lounges, and the turned oak legs keep it from looking heavy.', to_jsonb(array['Width 58 in · Depth 30 in · Height 32 in', 'Turned oak legs, unglued so they can be refinished', 'Single boxed seat cushion']::text[]), 186000, false, false, 'sofas Natural oak Linen Cream Walnut Leather Walnut', '2025-11-18T00:00:00Z');
