insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-000000000005', '00000001-0000-4000-8000-000000000002', 'wren-armchair', 'Wren Armchair', 'A generous lounge chair with a pitched back and oak arms worn smooth at the front edge. It is the chair people migrate to.', to_jsonb(array['Width 32 in · Depth 34 in · Height 31 in', 'Oak arms, linen or leather seat', 'Swivel base is not offered — the legs stay put']::text[]), 128000, true, true, 'chairs Natural oak Linen Ember Walnut Leather Walnut Natural oak Boucle Ivory', '2026-03-14T00:00:00Z');
