insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-000000000006', '00000001-0000-4000-8000-000000000002', 'rowan-dining-chair', 'Rowan Dining Chair', 'A spindle-back dining chair in solid oak. The seat is gently scooped, and the finish is oil, not a thick varnish, so it can be refreshed in the kitchen.', to_jsonb(array['Width 19 in · Depth 21 in · Height 33 in · Seat height 18 in', 'Solid oak, steam-bent back spindles', 'Sold individually — order two or eight']::text[]), 42000, false, true, 'chairs Natural oak Oak Sand Walnut stain Oak Walnut Natural oak Leather Black', '2025-10-02T00:00:00Z');
