insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-000000000008', '00000001-0000-4000-8000-000000000002', 'atelier-accent-chair', 'Atelier Accent Chair', 'A small upholstered chair with a wrapped back and rattan side panels. Useful beside a desk when someone stops to talk.', to_jsonb(array['Width 24 in · Depth 26 in · Height 31 in', 'Rattan panels, oak legs', 'Fabric is a tight weave, not a loose boucle']::text[]), 89000, false, false, 'chairs Natural oak Rattan Cream Walnut Rattan Sage', '2026-06-08T00:00:00Z');
