insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-00000000000a', '00000001-0000-4000-8000-000000000003', 'cinder-coffee-table', 'Cinder Coffee Table', 'A low table with an oak apron and a honed marble top the color of wet sand. The edge is eased so it does not bite a shin.', to_jsonb(array['Length 48 in · Width 24 in · Height 15 in', 'Honed marble over an oak frame', 'Marble is sealed; wipe spills, do not pretend it is invincible']::text[]), 98000, false, true, 'tables Natural oak Marble Cream Walnut Marble Ink', '2026-02-28T00:00:00Z');
