insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-00000000000c', '00000001-0000-4000-8000-000000000003', 'ash-writing-desk', 'Ash Writing Desk', 'A writing desk with a leather blotter inset and a single drawer deep enough for paper, not a cable graveyard. The ash is pale and straight-grained.', to_jsonb(array['Width 54 in · Depth 26 in · Height 30 in', 'Solid ash, vegetable-tanned leather inset', 'Drawer on soft-close runners', 'Cable notch at the back']::text[]), 172000, true, false, 'tables Natural ash Leather Sand Ebonized ash Leather Ink', '2026-07-01T00:00:00Z');
