insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-00000000000d', '00000001-0000-4000-8000-000000000004', 'solstice-platform-bed', 'Solstice Platform Bed', 'A low oak platform with a slatted headboard that lets the wall stay visible. No box spring. The mattress sits in a shallow recess so sheets tuck cleanly.', to_jsonb(array['Queen shown · King and full available in the same frame', 'Height to the top of the mattress deck: 10 in', 'Solid oak, center rail, and a row of slats', 'Headboard is part of the frame, not a bolt-on panel']::text[]), 248000, true, true, 'beds Natural oak Oak Sand Walnut Oak Walnut', '2026-03-03T00:00:00Z');
