insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-000000000012', '00000001-0000-4000-8000-000000000005', 'cedar-keeper-chest', 'Cedar Keeper Chest', 'A chest in aromatic cedar with an oak lid. Blankets, off-season coats, the good tablecloth. The hinge stops the lid before it hits the wall.', to_jsonb(array['Width 42 in · Depth 18 in · Height 20 in', 'Aromatic cedar body, oak lid and base', 'Soft-close lid stay']::text[]), 92000, false, false, 'storage Natural oak Oak Sand Walnut Oak Walnut', '2025-08-21T00:00:00Z');
