insert into public.reviews (id, product_id, author_name, rating, title, body, created_at) values ('00000005-0000-4000-8000-000000000018', '00000002-0000-4000-8000-000000000013', 'Priya Shah', 4, 'Long, so measure the wall', 'We had 74 inches and it fit with a finger on each side. Do not round down.', '2026-09-14T00:00:00Z');
insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-000000000014', '00000001-0000-4000-8000-000000000005', 'hollow-wardrobe', 'Hollow Wardrobe', 'A two-door wardrobe for a bedroom without a closet worth the name. Hanging rod on the left, shelves on the right, oak throughout.', to_jsonb(array['Width 48 in · Depth 22 in · Height 76 in', 'Hanging height 50 in', 'Soft-close doors', 'Must be anchored']::text[]), 264000, false, false, 'storage Natural oak Oak Sand Walnut Oak Walnut', '2026-06-19T00:00:00Z');
