insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-000000000015', '00000001-0000-4000-8000-000000000006', 'arc-floor-lamp', 'Arc Floor Lamp', 'A brass arc lamp with a linen shade. It reaches over a sofa without a table in the way, and the marble foot keeps it honest.', to_jsonb(array['Height 78 in · Reach 40 in', 'Brass stem, marble base, linen shade', 'E26 socket, LED recommended, bulb not included', 'In-line dimmer on the cord']::text[]), 64000, false, true, 'lighting Brass Brass Brass Blackened brass Brass Ink', '2026-03-28T00:00:00Z');
