insert into public.products (id, category_id, slug, name, description, details, price_cents, featured, bestseller, keywords, created_at) values ('00000002-0000-4000-8000-000000000016', '00000001-0000-4000-8000-000000000006', 'kiln-table-lamp', 'Kiln Table Lamp', 'A ceramic lamp thrown in a small kiln, glazed the color of a clay roof. The shade is a plain drum in off-white paper.', to_jsonb(array['Height with shade 22 in', 'Stoneware base, paper shade', 'Each base varies slightly in the glaze', 'Bulb not included']::text[]), 28000, true, false, 'lighting Ember glaze Ceramic Ember Sand glaze Ceramic Sand Ink glaze Ceramic Ink', '2026-01-15T00:00:00Z');
